create extension if not exists pgcrypto;
create type public.app_role as enum ('ADMIN','APPROVER_1','APPROVER_2');
create type public.order_status as enum ('PENDING_APPROVAL_1','PENDING_APPROVAL_2','APPROVED','DECLINED');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role public.app_role not null default 'ADMIN', created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text not null, price integer not null check(price>=0), available_sizes text[] not null default array['XS','S','M','L'] check (available_sizes <@ array['XS','S','M','L']), inventory integer not null default 0 check(inventory>=0), is_available boolean not null default true, display_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_images (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, storage_path text not null, display_order integer not null default 0, created_at timestamptz not null default now());
create table public.business_settings (id uuid primary key default gen_random_uuid(), bank_name text not null default '[BANK NAME]', account_name text not null default '[ACCOUNT NAME]', account_number text not null default '[ACCOUNT NUMBER]', branch text not null default '[BRANCH]', delivery_fee integer not null default 0 check(delivery_fee>=0), whatsapp_number text not null default '[WHATSAPP NUMBER]', google_review_url text not null default '[GOOGLE REVIEW URL]', instagram_url text not null default '[INSTAGRAM URL]', facebook_url text not null default '[FACEBOOK URL]', tiktok_url text not null default '[TIKTOK URL]', delivery_information text not null default '[DELIVERY INFORMATION]', updated_at timestamptz not null default now());
create sequence public.order_number_seq start 1000;
create table public.orders (id uuid primary key default gen_random_uuid(), order_number bigint not null unique default nextval('public.order_number_seq'), customer_name text not null, customer_phone text not null, delivery_address text not null, additional_notes text, subtotal integer not null check(subtotal>=0), delivery_fee integer not null check(delivery_fee>=0), total integer not null check(total>=0), status public.order_status not null default 'PENDING_APPROVAL_1', idempotency_key uuid not null unique, submitted_at timestamptz not null default now(), approved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid not null references public.products(id), product_name text not null, selected_size text not null check(selected_size in ('XS','S','M','L')), quantity integer not null check(quantity>0), unit_price integer not null check(unit_price>=0), line_total integer not null check(line_total>=0));
create table public.payment_slips (id uuid primary key default gen_random_uuid(), order_id uuid not null unique references public.orders(id) on delete cascade, storage_path text not null, uploaded_at timestamptz not null default now());
create table public.approval_history (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, approval_stage smallint not null check(approval_stage in (1,2)), status public.order_status not null check(status in ('PENDING_APPROVAL_2','APPROVED','DECLINED')), approver_id uuid not null references public.profiles(id), comment text, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.products enable row level security; alter table public.product_images enable row level security; alter table public.business_settings enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payment_slips enable row level security; alter table public.approval_history enable row level security;
create function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid()) $$;
create policy "public can view available products" on public.products for select using (is_available); create policy "public can view product images" on public.product_images for select using (true); create policy "public can view settings" on public.business_settings for select using (true);
create policy "staff full products" on public.products for all using (public.is_staff()) with check(public.is_staff()); create policy "staff full product images" on public.product_images for all using (public.is_staff()) with check(public.is_staff()); create policy "staff settings" on public.business_settings for all using (public.is_staff()) with check(public.is_staff()); create policy "staff orders" on public.orders for all using (public.is_staff()) with check(public.is_staff()); create policy "staff order items" on public.order_items for all using (public.is_staff()) with check(public.is_staff()); create policy "staff slips" on public.payment_slips for all using (public.is_staff()) with check(public.is_staff()); create policy "staff history" on public.approval_history for select using (public.is_staff());
insert into storage.buckets (id,name,public) values ('product_images','product_images',true),('payment_slips','payment_slips',false) on conflict do nothing;
create policy "public product image access" on storage.objects for select using(bucket_id='product_images'); create policy "staff manage product images" on storage.objects for all using(bucket_id='product_images' and public.is_staff()) with check(bucket_id='product_images' and public.is_staff()); create policy "staff read slips" on storage.objects for select using(bucket_id='payment_slips' and public.is_staff());
